files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-inline-size: 360px;
  min-block-size: 100%;
  margin: 0;
  color: #000;
  font-family: 'Open Sans', sans-serif;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
}

h1,
h2,
h3,
p {
  margin: 0;
  padding: 0;
}

.article {
  display: flex;
  gap: 3%;
  inline-size: 60%;
  margin: auto;
  padding: 2em;
  background-color: #5f0dee;
}

.article__image {
  inline-size: 300px;
  border-radius: 50%;
  aspect-ratio: 1 / 1;
}

.quote {
  block-size: 30%;
  margin: 0;
  border: 1px solid #000;
  padding: 10px;
  background-color: #6dc1fd;
}

.quote__title {
  margin-block-end: 20px;
  font-size: 32px;
  line-height: 48px;
}

.quote__text {
  margin-block-end: 8px;
  font-size: 20px;
  line-height: 30px;
}

.quote__author {
  font-size: 14px;
  line-height: 21px;
}

@media (width <= 880px) {
  .article {
    flex-direction: column;
    height: 150vw;
    inline-size: 100%;
    padding: 0.6em;
  }

  .article__image {
    align-self: center;
    inline-size: 200px;
    block-size: 200px;
  }
}
